local function install_offline_resources()
    for _,asset in pairs(offline_asset_files) do
        if readfile(asset.path)==nil then
            writefile(asset.path,asset.body)
            assert(readfile(asset.path)==asset.body,'angelwings: cannot write '..asset.path)
        end
    end
end
local offline_http={}
function offline_http.get(url,options,callback)
    if type(options)=='function' and callback==nil then callback=options end
    assert(type(callback)=='function','angelwings: missing resource callback')
    local asset=assert(offline_asset_files[url],'angelwings: unknown offline resource '..tostring(url))
    local body=assert(readfile(asset.path),'angelwings: missing resource '..asset.path)
    client.delay_call(0,function()
        callback(true,{status=200,body=body,headers={['content-length']=tostring(#body)}})
    end)
end

