        W[5] = false;
    end
    ::pc_56::
    do
        if (not (a)) then
            do return W[5] end
        else
            for p,l,V in next,a do
                if (not ((p >= 1))) then
                else
                    (l)[3] = (l);
                    (l)[1] = (W[p]);
                    (l)[2] = 1;
                    a[p] = nil;
                end
            end
            do return W[5] end
        end
    end
end
end

